    use super::*;

    #[test]
    fn interleave_empty() {
        let s1 = vec![];
        let s2 = vec![];
        let s3 = vec![];
        let out = interleave(&s1, &s2, &s3);
        assert_eq!(out, Vec::<i32>::new());
    }

    #[test]
    fn interleave_basic() {
        let s1 = vec![1, 2, 3];
        let s2 = vec![10, 20, 30];
        let s3 = vec![-1, -2, -3];
        let out = interleave(&s1, &s2, &s3);
        assert_eq!(out, vec![1, 10, -1, 2, 20, -2, 3, 30, -3]);
    }

    #[test]
    #[should_panic]
    fn interleave_mismatched_lengths_panics() {
        let s1 = vec![1, 2];
        let s2 = vec![3];
        let s3 = vec![4, 5];
        let _ = interleave(&s1, &s2, &s3);
    }
